	importButton.AddCSSClass("suggested-action")
	importButton.SetSensitive(false)

	cancelButton := gtk.NewButtonWithLabel("Cancel")

	buttonBox.Append(cancelButton)
	buttonBox.Append(importButton)
	mainBox.Append(buttonBox)

