	tooltipWindow := gtk.NewWindow(gtk.WindowTypePopup)
	tooltipWindow.SetSizeRequest(80, 24)
	tooltipWindow.SetDecorated(false)
	tooltipWindow.SetResizable(false)
	tooltipWindow.SetName("waveform-tooltip")

